    private static final Map<String, ConfigHandler<?>> HANDLERS = new ConcurrentHashMap();
    private static final Map<String, Class<?>> CONFIG_TYPES = new ConcurrentHashMap();

    public static <T> T getConfig(Class<T> configClass, String id, Logger logger) {
        ConfigHandler<?> handler = Config.initializeIfNeeded(configClass, id, logger);
        Object config = handler.getConfig();
        if (configClass.isInstance(config)) {
            return configClass.cast(config);
        }
        throw new IllegalStateException("ConfigHandler returned config of type " + config.getClass().getName() + ", expected " + configClass.getName());
    }

    public static void initConfigScreen(ModContainer container, String id) {
        container.registerExtensionPoint(ConfigScreenHandler.ConfigScreenFactory.class, () -> new ConfigScreenHandler.ConfigScreenFactory((client, parent) -> Config.createConfigScreen(id, parent)));
    }

    public static Screen createConfigScreen(String id, Screen parent) {
        ConfigHandler<?> handler = HANDLERS.get(id);
        if (handler != null) {
            return handler.createConfigScreen(parent);
        }
        throw new IllegalStateException("Config handler for id '" + id + "' is not initialized. Call getConfig(...) first.");
    }

    private static <T> ConfigHandler<?> initializeIfNeeded(Class<T> configClass, String id, Logger logger) {
        CONFIG_TYPES.compute(id, (key, existingClass) -> {
